import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;

public class Main {
    // 元信息：保留到运行时，注解本身不产生行为
    @Retention(RetentionPolicy.RUNTIME)
    @Target({ElementType.FIELD, ElementType.METHOD})
    @interface Label {
        String value();
    }

    static class User {
        @Label("display-name")
        private String name;

        private User(String name) {
            this.name = name;
        }

        @Label("greeting")
        private String greet(String prefix) {
            return prefix + ", " + name;
        }
    }

    // 模拟框架的元数据缓存
    private static final Map<String, Method> methodCache = new HashMap<>();
    private static final Map<String, Field> fieldCache = new HashMap<>();

    public static void main(String[] args) throws Throwable {
        demonstrateClassLoaderIdentity();
        demonstrateAccessAPIs();
        demonstrateAnnotationRetention();
        demonstrateModuleBoundary();
        demonstrateCachePerformance();
    }

    // 1. Class 镜像由 ClassLoader 共同决定
    static void demonstrateClassLoaderIdentity() throws ClassNotFoundException {
        Class<User> literal = User.class;           // 不触发初始化
        Class<?> forName = Class.forName("Main$User"); // 触发初始化
        System.out.println("same Class object: " + (literal == forName)); // true（同一 ClassLoader）
    }

    // 2. getDeclaredXxx vs getXxx、setAccessible
    static void demonstrateAccessAPIs() throws Exception {
        Class<User> cls = User.class;

        // getDeclaredConstructor 能拿到 private 构造器
        Constructor<User> ctor = cls.getDeclaredConstructor(String.class);
        ctor.setAccessible(true);  // 跳过语言层访问检查
        User user = ctor.newInstance("Ada");

        // getDeclaredField 能拿到 private 字段
        Field nameField = cls.getDeclaredField("name");
        nameField.setAccessible(true);
        System.out.println("get value: " + nameField.get(user));
        nameField.set(user, "Grace");

        // getDeclaredMethod 能拿到 private 方法
        Method greet = cls.getDeclaredMethod("greet", String.class);
        greet.setAccessible(true);
        String result = (String) greet.invoke(user, "Hi");
        System.out.println("reflect invoke: " + result);

        // InvocationTargetException 包装了真实异常
        // 真实框架里要 catch InvocationTargetException 并 getCause()
    }

    // 3. 注解保留阶段：只有 RUNTIME 能被普通反射读到
    static void demonstrateAnnotationRetention() throws Exception {
        Class<User> cls = User.class;
        Field nameField = cls.getDeclaredField("name");
        Method greet = cls.getDeclaredMethod("greet", String.class);

        Label fieldLabel = nameField.getAnnotation(Label.class);
        Label methodLabel = greet.getAnnotation(Label.class);
        System.out.println("field @Label: " + fieldLabel.value());   // display-name
        System.out.println("method @Label: " + methodLabel.value()); // greeting
        // 如果 @Retention 是 SOURCE 或 CLASS，getAnnotation 返回 null
    }

    // 4. JPMS 模块边界：setAccessible 不能无条件穿透
    static void demonstrateModuleBoundary() throws Throwable {
        // String 是 java.base 模块的类，其 value 字段不会对应用代码开放
        Field stringValue = String.class.getDeclaredField("value");
        boolean accessible = stringValue.trySetAccessible();
        System.out.println("String.value trySetAccessible: " + accessible); // 通常 false
        // 尝试 setAccessible(true) 会抛 InaccessibleObjectException
    }

    // 5. MethodHandle 是更明确的替代路径
    static void demonstrateCacheAndMethodHandle() throws Throwable {
        User user = User.class.getDeclaredConstructor(String.class)
                .newInstance("Hopper");

        // MethodHandle：privateLookupIn 需要模块 opens 或同模块
        MethodHandle privateGreet = MethodHandles.privateLookupIn(User.class, MethodHandles.lookup())
                .findVirtual(User.class, "greet",
                        MethodType.methodType(String.class, String.class));
        String mhResult = (String) privateGreet.invoke(user, "Hello");
        System.out.println("MethodHandle invoke: " + mhResult);
    }

    // 模拟框架的缓存策略：初始化时缓存，运行时复用
    static void demonstrateCachePerformance() throws Exception {
        Class<User> cls = User.class;
        // 初始化阶段：缓存 Method
        Method cachedGreet = cls.getDeclaredMethod("greet", String.class);
        cachedGreet.setAccessible(true);
        methodCache.put("User.greet", cachedGreet);

        // 运行阶段：从缓存取，不再查找
        User user = cls.getDeclaredConstructor(String.class).newInstance("Cache");
        Method m = methodCache.get("User.greet");
        String cached = (String) m.invoke(user, "Hi");
        System.out.println("cached invoke: " + cached);
    }
}
